.scrim {
  z-index: -1;
  background: linear-gradient(90deg, rgb(9 8 10 / 64%), rgb(9 8 10 / 16%));
  transition: opacity 220ms ease-out;
}

.root:hover .scrim,
.root:focus-visible .scrim {
  opacity: 0.68;
}

.content {
  position: relative;
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  text-shadow: 0 1px 6px rgb(0 0 0 / 56%);
  font-size: 13px;
  font-weight: 660;
  letter-spacing: -0.013em;
  white-space: nowrap;
}

.gem {
  display: grid;
  width: 31px;
  height: 31px;
  flex: 0 0 31px;
  place-items: center;
  border: 1px solid rgb(255 255 255 / 14%);
  border-radius: 9px;
  background: rgb(10 9 11 / 34%);
  backdrop-filter: blur(5px);
  transition: transform 220ms cubic-bezier(0.2, 0, 0, 1);
}

.gem svg {
  width: 17px;
  height: 17px;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.15;
}

.root:hover .gem,
.root:focus-visible .gem {
  transform: rotate(6deg) scale(1.04);
}

@media (prefers-reduced-motion: reduce) {
  .root,
  .material,
  .scrim,
  .gem {
    transition: none;
  }

  .root:hover,
  .root:active,
  .root:hover .material,
  .root:focus-visible .material,
  .root:hover .gem,
  .root:focus-visible .gem {
    transform: none;
  }
}

@media (forced-colors: active) {
  .root {
    color: ButtonText;
    border-color: ButtonText;
    background: ButtonFace;
    box-shadow: none;
  }

  .material,
  .scrim {
    display: none;
  }

  .content {
    text-shadow: none;
  }

  .gem {
    border-color: ButtonText;
    background: ButtonFace;
    backdrop-filter: none;
  }
}
